"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit of the 'api' container from 500m to 750m to clear throttling, based on evidence of sustained CPU usage near the limit and readiness probe failures.",
  "rationale": "The container is throttled at 60% of its CPU periods (0.5) with usage at 0.495 (99% of limit). The new version (4.2.0) uses more CPU than the previous version (4.1.3), as shown by higher usage (88% vs 50%) and throttling. Increasing the limit to 750m (1.5x current) should resolve the throttling without affecting memory or other resources.",
